public sealed interface ConnectionState
        permits Disconnected, Connecting, Connected {}

record Disconnected() implements ConnectionState {}
record Connecting(Instant initiated) implements ConnectionState {}
record Connected(String sessionId) implements ConnectionState {}

String describe(ConnectionState state) {
    return switch (state) {              // no default: the set is closed
        case Disconnected d -> "down";
        case Connecting c   -> "connecting since " + c.initiated();
        case Connected c    -> c.sessionId();
    };
}

