public abstract class ConnectionState {          // closed by convention
    ConnectionState() {}                        // package-private constructor
    public abstract <R> R accept(Visitor<R> v);
    public interface Visitor<R> {
        R disconnected(Disconnected d);
        R connecting(Connecting c);
        R connected(Connected c);
    }
}
final class Connected extends ConnectionState {
    private final String sessionId;
    public <R> R accept(Visitor<R> v) { return v.connected(this); }
}
